add_action('admin_footer',function(){if(($_GET['page']??'')!=='eyedonation-migrations'||!current_user_can('manage_options'))return;echo '<div class="wrap" id="edm-givingtuesday"><h2>027 — Editable Giving Tuesday page</h2><p>Replaces /givingtuesday/ with the approved block layout or creates that page when missing. Assigns the Giving Tuesday template and disables the builder only for this page. Existing builder data is retained. Status: '.esc_html(history()[GivingTuesdayMigration::ID]['status']??'pending').'</p><p>'.esc_html(get_option('edm_givingtuesday_notice','')).'</p>';foreach(['preview'=>'Preview Giving Tuesday','run'=>'Install / Resume Giving Tuesday'] as $mode=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="edm_givingtuesday_'.$mode.'">';wp_nonce_field('edm_givingtuesday_'.$mode);if($mode==='run')echo '<label><input type="checkbox" name="backup" value="1" required> I have a recoverable backup.</label><br><label><input type="checkbox" name="replace" value="1" required> Replace the Giving Tuesday content with the previewed design.</label>';submit_button($label);echo '</form>';}$p=get_option('edm_givingtuesday_preview');if($p)echo '<details><summary>Current / proposed page fields</summary><pre>'.esc_html(wp_json_encode($p,JSON_PRETTY_PRINT)).'</pre></details>';echo '</div>';});
